local UIFightTeamContinuousFightPopupDialog = Class("UIFightTeamContinuousFightPopupDialog")

function UIFightTeamContinuousFightPopupDialog:__init() 
    self._curQuestId = 0
    self._curSelectType = 0
    self._isAutoUse = false
    self._curNum = 1
    self._isTrue = false

    self._maxNum = 99
end

function UIFightTeamContinuousFightPopupDialog:__delete()
    self._curQuestId = 0
    self._curSelectType = 0
    self._isAutoUse = false
    self._curNum = 1
    self._isTrue = false
    
    self._maxNum = 99
end

function UIFightTeamContinuousFightPopupDialog:Awake()
    SetButtonAction(self.BtnClose, Bind(self, self.OnBtnClose))
    SetButtonAction(self.ClickClose, Bind(self, self.OnBtnClose))
    SetButtonAction(self.FontStyleWithIconButton, Bind(self, self.OnBtnSure))
    SetButtonAction(self.BtnAutoUse, Bind(self, self.OnBtnAutoUse))

    SetButtonAction(self.BtnReduce, Bind(self, self.OnBtnMinus))
    SetButtonAction(self.BtnAdd, Bind(self, self.OnBtnAdd))
    SetButtonAction(self.BtnMax, Bind(self, self.OnBtnAddTen))
    SetButtonAction(self.BtnMin, Bind(self, self.OnBtnMinusTen))

    SetToggleValueChanged(self.ToggleCell, Bind(self, self.OnToggleNoLimit))
    SetToggleValueChanged(self.ToggleCell2, Bind(self, self.OnToggleTagertNum))
    self.InputField.onValueChanged:AddListener(function(num)
        num = checkNumber(num)
        if num <= 1 then
            self._curNum = 1
        elseif num >= self._maxNum then
            self._curNum = self._maxNum
        else
            self._curNum = num
        end
        self:RefreshSelectNum()
    end)
end

function UIFightTeamContinuousFightPopupDialog:FillSelf()
    local useId = self:GetUseGoodsId()
    if useId <= 0 then
        CfUtils.SetActive(self.Setting, false)
        return
    end

    CfUtils.RefeshGoodGo2(self.GoodNode, useId, GoodsUtils.GetThingNo(useId), nil, nil, function()
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(useId)
        GameUtils.ShowCommonTipsBoard(self.GoodNode, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)  
    end)
end

function UIFightTeamContinuousFightPopupDialog:GetUseGoodsId()
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._curQuestId)
    local useId = checkNumber(vo.costItem)

    local t = CfUtils.GetCf(AutoIds.IdSetting302, "ExchangeStrengthVo", true)
    for k, v in pairs(t) do
        if checkNumber(v.getItemId) == useId then
            return checkNumber(v.itemId)
        end
    end
    return 0
end

function UIFightTeamContinuousFightPopupDialog:OnBtnAutoUse()
    self._isAutoUse = not self._isAutoUse

    if self._isAutoUse then
        CfUtils.PlayAnimation(self.AnimRoot, "BtnContinuousFight_On")
    else
        CfUtils.PlayAnimation(self.AnimRoot, "BtnContinuousFight_Off")
    end
    CfUtils.SetActive(self.GoodNode.transform:Find("Container/UIFX_GoodsGlow"), self._isAutoUse)
end

function UIFightTeamContinuousFightPopupDialog:InitData()

end

function UIFightTeamContinuousFightPopupDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local argument = self.controller.Argument.parameters
        self._curQuestId = checkNumber(argument.questId)
        if self._curQuestId <= 0 then
            return
        end

        self:InitData()
        self:FillSelf()
    end))
    return coWait
end

--无限制
function UIFightTeamContinuousFightPopupDialog:OnToggleNoLimit(isTrue)
    if isTrue then
        self.ToggleCell2.isOn = false
        self._curSelectType = Constants.ContinueBattleType.NoLimit
        CfUtils.SetActive(self.ToggleCell.transform:Find("Background/Checkmark"), isTrue)
        CfUtils.SetActive(self.ToggleCell2.transform:Find("Background/Checkmark"), false)
        CfUtils.SetActive(self.ChooseNumberNode, false)
    else 
    end
end

--次数
function UIFightTeamContinuousFightPopupDialog:OnToggleTagertNum(isTrue)
    if isTrue then
        CfUtils.SetActive(self.ChooseNumberNode,isTrue)
        self.ToggleCell.isOn = false
        self._curSelectType = Constants.ContinueBattleType.TargetNum
        self._curNum = 1
        self:RefreshSelectNum()
        CfUtils.SetActive(self.ToggleCell2.transform:Find("Background/Checkmark"), isTrue)
        CfUtils.SetActive(self.ToggleCell.transform:Find("Background/Checkmark"), false)
    else
    end
end

function UIFightTeamContinuousFightPopupDialog:RefreshSelectNum()
    self.InputField.text = self._curNum
end

function UIFightTeamContinuousFightPopupDialog:OnBtnAdd()
    if checkNumber(self._curNum) >= checkNumber(self._maxNum) then
        GameUtils.Toast(localize("当前已是最大值"))
        return
    end

    self._curNum = checkNumber(self._curNum) + 1
    self:RefreshSelectNum()
end

function UIFightTeamContinuousFightPopupDialog:OnBtnAddTen()
    if checkNumber(self._curNum) >= checkNumber(self._maxNum) then
        GameUtils.Toast(localize("当前已是最大值"))
        return
    end

    self._curNum = checkNumber(self._curNum) + 10

    if checkNumber(self._curNum) >= self._maxNum  then
        self._curNum = self._maxNum
    elseif checkNumber(self._curNum) <= 1 then
        self._curNum = 1
    end

    self:RefreshSelectNum()
end

function UIFightTeamContinuousFightPopupDialog:OnBtnMinus()
    if checkNumber(self._curNum) <= 1 then
        GameUtils.Toast(localize("当前已是最小值"))
        return
    end

    self._curNum = checkNumber(self._curNum) - 1
    self:RefreshSelectNum()
end

function UIFightTeamContinuousFightPopupDialog:OnBtnMinusTen()
    if checkNumber(self._curNum) <= 1 then
        GameUtils.Toast(localize("当前已是最小值"))
        return
    end

    self._curNum = checkNumber(self._curNum) - 10

    if checkNumber(self._curNum) >= self._maxNum  then
        self._curNum = self._maxNum
    elseif checkNumber(self._curNum) <= 1 then
        self._curNum = 1
    end

    self:RefreshSelectNum()
end

function UIFightTeamContinuousFightPopupDialog:OnBtnClose()
    UIModule.CloseDialog(self.controller)
end

function UIFightTeamContinuousFightPopupDialog:OnBtnSure()
    teamComponent:SetIsOpenContinue(true, self._curSelectType, self._isAutoUse, self._curNum)
    Events.Broadcast(Constants.EventNames.ContinueBattle)
    self:OnBtnClose()
end

function UIFightTeamContinuousFightPopupDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

function UIFightTeamContinuousFightPopupDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.ToggleCell.isOn = true

        if self._isAutoUse then
            CfUtils.PlayAnimation(self.AnimRoot, "BtnContinuousFight_On")
        else
            CfUtils.PlayAnimation(self.AnimRoot, "BtnContinuousFight_Off")
        end
    end))
    return coWait
end

return UIFightTeamContinuousFightPopupDialog
